mapper.select:
select pt.id,pt.fmcode,pt.title,pt.filesize,nvl(kz.clbz,'0') as clbz,kz.rootpath,kz.filepath
from doc_fileinfo pt left outer join doc_fileinfo_kz kz on (pt.id = kz.id)
where pt.busitype = 'sbxx' and  pt.busikey = #{sbid}

select hz.id as sbid,hz.sbywb_dm,pt.id as fileid,pt.fmcode,pt.title,pt.filesize,pt.note,pt.rootpath,pt.filepath,dab.nsrsbh
from doc_fileinfo pt,sb_sbxx_hz hz left join gs_dj_cktmsdab dab on (hz.nsrdzdah = dab.nsrdzdah)
where pt.id = #{fileId} and pt.busikey = hz.id

select id,clbz
from DOC_FILEINFO_KZ
where id = #{fileId}

select h.id,h.sbywb_dm as sbywbDm,to_char(h.sbpc)as sbpc,sssq,c.qyhgdm
from sb_sbxx_hz h  left join gs_dj_cktmsdab c on (c.nsrdzdah = h.nsrdzdah)
where h.id = #{id} and rownum = 1
